// writerStubCommitSubject returns the subject of [stub.Behaviour] for
// Commit. The subject calls a new double that reports to tb.
func writerStubCommitSubject(tb assert.TB) stub.Subject[storetest.WriterCommitCall, storetest.WriterCommitReturn] {
	tb.Helper()
	s := storetest.NewWriterStub(tb)
	return stub.Subject[storetest.WriterCommitCall, storetest.WriterCommitReturn]{
		Stub: s.OnCommit.MethodStub,
		Call: func() {
			_, _ = writerStubCommit(tb, s)
		},
		Result: func() storetest.WriterCommitReturn {
			got0, got1 := writerStubCommit(tb, s)
			return storetest.WriterCommitReturn{Result: got0, Err: got1}
		},
		Override: func(mark func()) {
			s.OnCommit.Func(func(_ context.Context, _ epoch.Epoch, _ *store.Mutation) (epoch.Epoch, error) {
				mark()
				var z0 epoch.Epoch
				var z1 error
				return z0, z1
			})
		},
		Fails: func() error {
			_, r1 := writerStubCommit(tb, s)
			return r1
		},
	}
}

// writerStubInstance is the instance of a storetest.WriterStub that the
// checks of the constructors and the options drive.
type writerStubInstance = stub.Instance[storetest.WriterCommitCall]

// writerStubInstanceOf returns the instance of s. The options apply to the
// whole double, so the checks call Commit alone.
func writerStubInstanceOf(tb assert.TB, s *storetest.WriterStub) writerStubInstance {
	tb.Helper()
	return writerStubInstance{
		Stub: s.OnCommit.MethodStub,
		Call: func() {
			_, _ = writerStubCommit(tb, s)
		},
		Reset: s.ResetCalls,
	}
}

// TestWriterStub checks the methods, the constructors and the options of
// the double WriterStub.
func TestWriterStub(t *testing.T) {
	t.Parallel()

	t.Run("Commit", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Commit", writerStubCommitSubject)

		t.Run("records the arguments of the call", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewWriterStub(t)
			_, _ = writerStubCommit(t, s)
			got := s.OnCommit.AssertCalledOnce(t, "Commit records the call")
			a0, a1, a2 := writerStubCommitArgs(t)
			expect.Equal(t, got.Ctx, a0, "the call records Ctx", expect.ByIdentity())
			expect.Equal(t, got.Expect, a1, "the call records Expect")
			expect.Equal(t, got.M, a2, "the call records M")
		})

		t.Run("runs the OnRecord hook once for each call", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewWriterStub(t)
			var seen []storetest.WriterCommitCall
			s.OnCommit.OnRecord(func(c storetest.WriterCommitCall) { seen = append(seen, c) })
			_, _ = writerStubCommit(t, s)
			_, _ = writerStubCommit(t, s)
			assert.Length(t, seen, 2, "OnRecord runs once for each call of Commit")
		})
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()
		stub.ResetBehaviour(t, func(tb assert.TB) writerStubInstance {
			return writerStubInstanceOf(tb, storetest.NewWriterStub(tb))
		})

		t.Run("clears the recorded calls of Commit", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewWriterStub(t)
			_, _ = writerStubCommit(t, s)
			s.ResetCalls()
			assert.Equal(t, s.OnCommit.CallCount(), 0, "ResetCalls clears the calls of Commit")
		})

		t.Run("keeps the results of Returns of Commit", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewWriterStub(t)
			want0, want1 := writerStubCommitPins()
			s.OnCommit.Returns(want0, want1)
			s.ResetCalls()
			got0, got1 := writerStubCommit(t, s)
			expect.Equal(t, got0, want0, "ResetCalls keeps the Result of Commit")
			expect.ErrorIs(t, got1, want1, "ResetCalls keeps the error of Commit")
		})
	})

	t.Run("NewWriterStubDelayed", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) writerStubInstance {
			return writerStubInstanceOf(tb, storetest.NewWriterStubDelayed(tb, d, clk))
		})
	})

	t.Run("NewWriterStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails Commit with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Commit-failing")
			s := storetest.NewWriterStubFailing(t, want)
			_, r1 := writerStubCommit(t, s)
			assert.ErrorIs(t, r1, want, "Commit fails with the error of NewWriterStubFailing")
		})
	})

	t.Run("WriterStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) writerStubInstance {
			return writerStubInstanceOf(tb, storetest.NewWriterStub(tb, storetest.WriterStubStrict()))
		})
	})

	t.Run("WriterStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes Commit to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := storetest.NewWriterStub(t)
			s := storetest.NewWriterStub(t, storetest.WriterStubDelegateTo(inner))
			_, _ = writerStubCommit(t, s)
			inner.OnCommit.AssertCalledOnce(t, "Commit calls the implementation")
		})

		t.Run("fails Commit with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Commit-delegate")
			inner := storetest.NewWriterStub(t)
			inner.OnCommit.Faults(want, 1)
			s := storetest.NewWriterStub(t, storetest.WriterStubDelegateTo(inner))
			_, r1 := writerStubCommit(t, s)
			assert.ErrorIs(t, r1, want, "Commit fails with the error of the implementation")
		})
	})

	t.Run("WriterStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) writerStubInstance {
			return writerStubInstanceOf(tb, storetest.NewWriterStub(tb, storetest.WriterStubWithClock(clk)))
		})
	})

	t.Run("WriterStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) writerStubInstance {
			return writerStubInstanceOf(tb, storetest.NewWriterStub(tb, storetest.WriterStubWithRandSource(src)))
		})
	})

	t.Run("WriterStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) writerStubInstance {
			return writerStubInstanceOf(tb, storetest.NewWriterStub(tb, storetest.WriterStubBenchMode()))
		})
	})

	t.Run("WriterStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) writerStubInstance {
			return writerStubInstanceOf(
				tb,
				storetest.NewWriterStub(tb, storetest.WriterStubWithClock(clk), storetest.WriterStubWithLatency(d)),
			)
		})
	})

	t.Run("WriterStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails Commit with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Commit-failing")
			s := storetest.NewWriterStub(t, storetest.WriterStubFailing(want))
			_, r1 := writerStubCommit(t, s)
			assert.ErrorIs(t, r1, want, "Commit fails with the error of WriterStubFailing")
		})
	})

	t.Run("WithWriterCommit", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Commit", func(t *testing.T) {
			t.Parallel()
			called := false
			s := storetest.NewWriterStub(
				t,
				storetest.WithWriterCommit(
					func(_ context.Context, _ epoch.Epoch, _ *store.Mutation) (epoch.Epoch, error) {
						called = true
						var z0 epoch.Epoch
						var z1 error
						return z0, z1
					},
				),
			)
			_, _ = writerStubCommit(t, s)
			assert.True(t, called, "WithWriterCommit sets the function of Commit")
		})
	})
}

