// TestStoreWatchStub checks the methods of StoreWatchStub, which
// configures Watch.
func TestStoreWatchStub(t *testing.T) {
	t.Parallel()

	t.Run("Returns", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the results of each call of Watch", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewStoreStub(t)
			want0 := storeStubWatchPins()
			s.OnWatch.Returns(want0)
			got0 := storeStubWatch(t, s)
			assert.Equal(t, got0, want0, "Watch returns the Result that Returns sets")
		})

		t.Run("configures Watch for strict mode", func(t *testing.T) {
			t.Parallel()
			r := assert.NewRecorder()
			s := storetest.NewStoreStub(r)
			s.OnWatch.Strict()
			var want0 iter.Seq2[store.Event, error]
			s.OnWatch.Returns(want0)
			_ = storeStubWatch(t, s)
			assert.False(t, r.Failed(), "strict mode accepts the call of Watch")
		})
	})

	t.Run("Func", func(t *testing.T) {
		t.Parallel()

		t.Run("passes the arguments of each call of Watch to the function", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewStoreStub(t)
			var got0 context.Context
			var got1 shard.Scope
			var got2 shard.NamespaceIncarnation
			var got3 epoch.Epoch
			var got4 shard.NodeID
			s.OnWatch.Func(
				func(p0 context.Context, p1 shard.Scope, p2 shard.NamespaceIncarnation, p3 epoch.Epoch, p4 shard.NodeID) iter.Seq2[store.Event, error] {
					got0, got1, got2, got3, got4 = p0, p1, p2, p3, p4
					var z0 iter.Seq2[store.Event, error]
					return z0
				},
			)
			_ = storeStubWatch(t, s)
			a0, a1, a2, a3, a4 := storeStubWatchArgs(t)
			expect.Equal(t, got0, a0, "the function receives Ctx", expect.ByIdentity())
			expect.Equal(t, got1, a1, "the function receives S")
			expect.Equal(t, got2, a2, "the function receives Inc")
			expect.Equal(t, got3, a3, "the function receives From")
			expect.Equal(t, got4, a4, "the function receives Node")
		})
	})

	t.Run("Yields", func(t *testing.T) {
		t.Parallel()

		t.Run("yields each item", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewStoreStub(t)
			var want store.Event
			s.OnWatch.Yields(want, want)
			got0 := storeStubWatch(t, s)
			seen := 0
			for range got0 {
				seen++
			}
			assert.Equal(t, seen, 2, "Watch yields each item")
		})

		t.Run("stops yielding when the caller breaks", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewStoreStub(t)
			var want store.Event
			s.OnWatch.Yields(want, want, want)
			got0 := storeStubWatch(t, s)
			seen := 0
			for range got0 {
				seen++
				break
			}
			assert.Equal(t, seen, 1, "Watch stops when the caller breaks")
		})
	})

	t.Run("YieldsError", func(t *testing.T) {
		t.Parallel()

		t.Run("yields the error after the items", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewStoreStub(t)
			var item store.Event
			want := errors.New("Watch-yields")
			s.OnWatch.YieldsError([]store.Event{item, item}, want)
			got0 := storeStubWatch(t, s)
			seen := 0
			var last error
			for _, err := range got0 {
				if err != nil {
					last = err
					break
				}
				seen++
			}
			assert.Equal(t, seen, 2, "Watch yields each item before the error")
			assert.ErrorIs(t, last, want, "Watch ends with the error of YieldsError")
		})

		t.Run("stops the sequence when the caller breaks", func(t *testing.T) {
			t.Parallel()
			s := storetest.NewStoreStub(t)
			var item store.Event
			s.OnWatch.YieldsError([]store.Event{item, item, item}, errors.New("Watch-yields"))
			got0 := storeStubWatch(t, s)
			seen := 0
			for range got0 {
				seen++
				break
			}
			assert.Equal(t, seen, 1, "Watch stops when the caller breaks")
		})
	})
}

